class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        from collections import defaultdict
        cnt = defaultdict(int)
        subs = []
        for s in arr:
            st = {s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)}
            subs.append(st)
            for x in st:
                cnt[x] += 1
        res = []
        for st in subs:
            best = ""
            for x in st:
                if cnt[x] == 1 and (best == "" or len(x) < len(best)
                                    or (len(x) == len(best) and x < best)):
                    best = x
            res.append(best)
        return res

