class Solution {
public:
    vector<string> shortestSubstrings(vector<string>& arr) {
        unordered_map<string, int> cnt;
        vector<set<string>> subs(arr.size());
        for (size_t i = 0; i < arr.size(); i++) {
            auto& s = arr[i];
            for (size_t a = 0; a < s.size(); a++)
                for (size_t b = a + 1; b <= s.size(); b++)
                    subs[i].insert(s.substr(a, b - a));
            for (auto& x : subs[i]) cnt[x]++;
        }
        vector<string> res;
        for (auto& st : subs) {
            string best = "";
            for (auto& x : st)
                if (cnt[x] == 1 && (best.empty() || x.size() < best.size())) best = x;
            res.push_back(best);
        }
        return res;
    }
};

