class Solution {
    public String[] shortestSubstrings(String[] arr) {
        Map<String, Integer> cnt = new HashMap<>();
        List<TreeSet<String>> subs = new ArrayList<>();
        for (String s : arr) {
            TreeSet<String> st = new TreeSet<>();
            for (int a = 0; a < s.length(); a++)
                for (int b = a + 1; b <= s.length(); b++)
                    st.add(s.substring(a, b));
            subs.add(st);
            for (String x : st) cnt.merge(x, 1, Integer::sum);
        }
        String[] res = new String[arr.length];
        for (int i = 0; i < arr.length; i++) {
            String best = "";
            for (String x : subs.get(i))
                if (cnt.get(x) == 1 && (best.isEmpty() || x.length() < best.length())) best = x;
            res[i] = best;
        }
        return res;
    }
}

