struct Node {
    unordered_map<char, Node*> ch;
    int cnt = 0;
};
class Solution {
public:
    vector<string> shortestSubstrings(vector<string>& arr) {
        Node* root = new Node();
        for (auto& s : arr) {
            unordered_set<Node*> vis;
            for (size_t a = 0; a < s.size(); a++) {
                Node* cur = root;
                for (size_t b = a; b < s.size(); b++) {
                    auto it = cur->ch.find(s[b]);
                    Node* nx;
                    if (it == cur->ch.end()) { nx = new Node(); cur->ch[s[b]] = nx; }
                    else nx = it->second;
                    cur = nx;
                    if (!vis.count(cur)) { vis.insert(cur); cur->cnt++; }
                }
            }
        }
        vector<string> res;
        for (auto& s : arr) {
            set<string> subs;
            for (size_t a = 0; a < s.size(); a++)
                for (size_t b = a + 1; b <= s.size(); b++) subs.insert(s.substr(a, b - a));
            string best = "";
            for (auto& x : subs) {
                Node* cur = root;
                bool ok = true;
                for (char c : x) {
                    auto it = cur->ch.find(c);
                    if (it == cur->ch.end()) { ok = false; break; }
                    cur = it->second;
                }
                if (ok && cur->cnt == 1 && (best.empty() || x.size() < best.size())) best = x;
            }
            res.push_back(best);
        }
        return res;
    }
};

