class Solution {
    static class Node {
        Map<Character, Node> ch = new HashMap<>();
        int cnt = 0;
    }
    public String[] shortestSubstrings(String[] arr) {
        Node root = new Node();
        for (String s : arr) {
            Set<Node> vis = new HashSet<>();
            for (int a = 0; a < s.length(); a++) {
                Node cur = root;
                for (int b = a; b < s.length(); b++) {
                    cur = cur.ch.computeIfAbsent(s.charAt(b), z -> new Node());
                    if (vis.add(cur)) cur.cnt++;
                }
            }
        }
        String[] res = new String[arr.length];
        for (int i = 0; i < arr.length; i++) {
            TreeSet<String> subs = new TreeSet<>();
            for (int a = 0; a < arr[i].length(); a++)
                for (int b = a + 1; b <= arr[i].length(); b++) subs.add(arr[i].substring(a, b));
            String best = "";
            for (String x : subs) {
                Node cur = root;
                boolean ok = true;
                for (char c : x.toCharArray()) {
                    cur = cur.ch.get(c);
                    if (cur == null) { ok = false; break; }
                }
                if (ok && cur.cnt == 1 && (best.isEmpty() || x.length() < best.length())) best = x;
            }
            res[i] = best;
        }
        return res;
    }
}

